style.css:
@-moz-document domain("web.whatsapp.com") {
/* ── Variables ───────────────────────────────────────────────────────────── */
:root {
  --wa-bg-deepest:    #100810;
  --wa-bg-sidebar:    #140a10;
  --wa-bg-main:       #130912;
  --wa-bg-header:     #140a10;
  --wa-bg-input:      #1f0d18;
  --wa-bg-bubble-in:  #1f0d18;
  --wa-bg-bubble-out: #4a0d2a;
  --wa-bg-hover:      #1f0e18;
  --wa-bg-active:     #260d1c;
  --wa-accent:        #d4447a;
  --wa-accent-light:  #e0557f;
  --wa-accent-muted:  #9a5070;
  --wa-border:        #2e1020;
  --wa-border-light:  #3a1020;
  --wa-text-primary:  #e8c0d0;
  --wa-text-name:     #f0b8d0;
  --wa-text-preview:  #7a4060;
  --wa-text-link:     #d4447a;
  --wa-text-time:     #9a5070;
  --wa-tick:          #d4447a;
}

/* ── Global background ───────────────────────────────────────────────────── */
body,
#app,
#startup {
  background-color: var(--wa-bg-deepest) !important;
}

/* Every div/section that WhatsApp uses as a panel background */
body > div,
#app > div,
#app > div > div {
  background-color: var(--wa-bg-deepest) !important;
}

/* ── Sidebar (left panel) ────────────────────────────────────────────────── */
/* Target by aria-label and structural position */
[aria-label="Chat list"],
[aria-label="Chats"],
div[tabindex="-1"] > div > div:first-child,
div[role="grid"],
div[role="listbox"] {
  background-color: var(--wa-bg-sidebar) !important;
}

/* Sidebar header */
header {
  background-color: var(--wa-bg-header) !important;
  border-bottom: 0.5px solid var(--wa-border) !important;
}

/* Header title */
header h1,
header span[dir="auto"] {
  color: var(--wa-text-name) !important;
}

/* Header icon buttons */
header button,
header [role="button"] {
  color: var(--wa-accent-muted) !important;
}

header button svg,
header [role="button"] svg {
  fill: var(--wa-accent-muted) !important;
  color: var(--wa-accent-muted) !important;
}

/* ── Search bar ──────────────────────────────────────────────────────────── */
[role="searchbox"],
div[contenteditable][data-tab] {
  background-color: var(--wa-bg-input) !important;
  color: var(--wa-text-primary) !important;
  caret-color: var(--wa-accent) !important;
}

/* Search container pill */
[aria-label="Search input textbox"],
[title="Search or start new chat"] {
  background-color: var(--wa-bg-input) !important;
  border-radius: 20px !important;
  border: 0.5px solid var(--wa-border-light) !important;
}

/* ── Chat list items ─────────────────────────────────────────────────────── */
[role="row"],
[role="listitem"],
[data-testid="cell-frame-container"] {
  background-color: transparent !important;
  border-bottom: 0.5px solid #1f0d18 !important;
}

[role="row"]:hover,
[role="listitem"]:hover,
[data-testid="cell-frame-container"]:hover {
  background-color: var(--wa-bg-hover) !important;
}

/* Selected / active chat */
[role="row"][aria-selected="true"],
[role="listitem"][aria-selected="true"],
[data-testid="cell-frame-container"][aria-selected="true"] {
  background-color: var(--wa-bg-active) !important;
}

/* Chat name text */
[data-testid="cell-frame-title"] span,
[role="row"] span[dir="auto"],
[role="listitem"] span[dir="auto"] {
  color: var(--wa-text-name) !important;
}

/* Preview / last message text */
[data-testid="last-msg-status"] ~ span,
[role="row"] span[dir="ltr"],
[role="listitem"] .copyable-text span {
  color: var(--wa-text-preview) !important;
}

/* Timestamps */
[data-testid="cell-frame-primary-detail__right"] span,
[role="row"] [dir="auto"] + span,
span[class*="time"] {
  color: var(--wa-text-time) !important;
}

/* Unread badge */
[data-testid="icon-unread-count"],
span[aria-label*="unread"] {
  background-color: var(--wa-accent) !important;
  color: #fff0f5 !important;
}

/* ── Conversation (right panel) header ───────────────────────────────────── */
[data-testid="conversation-header"],
[aria-label*="conversation"] header,
[aria-label*="chat"] header {
  background-color: var(--wa-bg-header) !important;
  border-bottom: 0.5px solid var(--wa-border) !important;
}

[data-testid="conversation-info-header-chat-title"] span,
[data-testid="conversation-header"] span[dir="auto"] {
  color: var(--wa-text-name) !important;
}

/* Online / typing status */
[data-testid="conversation-header"] span[dir="ltr"],
[data-testid="subtitle-secondary"] span {
  color: var(--wa-accent) !important;
}

/* ── Chat background ─────────────────────────────────────────────────────── */
[data-testid="conversation-panel-messages"],
[data-testid="msg-container"],
[role="application"],
main {
  background-color: var(--wa-bg-main) !important;
}

/* Nuke the default wallpaper */
[data-testid="conversation-panel-messages"] > div,
[data-testid="conversation-panel-messages"] > div > div {
  background-color: var(--wa-bg-main) !important;
  background-image: none !important;
}

/* Date pill */
[data-testid="conv-timeline-item--date"] span,
[data-testid="msg-meta"] > span {
  background-color: #1f0d18 !important;
  color: var(--wa-text-time) !important;
  border: 0.5px solid var(--wa-border) !important;
  border-radius: 10px !important;
  padding: 3px 8px !important;
}

/* ── Message bubbles ─────────────────────────────────────────────────────── */

/* Incoming bubble */
.message-in .copyable-text,
.message-in [class*="bubble"],
.message-in > div > div > div {
  background-color: var(--wa-bg-bubble-in) !important;
  border: 0.5px solid var(--wa-border-light) !important;
  border-top-left-radius: 4px !important;
  border-top-right-radius: 14px !important;
  border-bottom-right-radius: 14px !important;
  border-bottom-left-radius: 14px !important;
}

/* Outgoing bubble */
.message-out .copyable-text,
.message-out [class*="bubble"],
.message-out > div > div > div {
  background-color: var(--wa-bg-bubble-out) !important;
  border: 0.5px solid #7a1848 !important;
  border-top-left-radius: 14px !important;
  border-top-right-radius: 14px !important;
  border-bottom-right-radius: 4px !important;
  border-bottom-left-radius: 14px !important;
}

/* Bubble text */
.message-in .selectable-text,
.message-in span[dir] {
  color: #e8c0d0 !important;
}

.message-out .selectable-text,
.message-out span[dir] {
  color: #f5d0e0 !important;
}

/* Timestamps in bubbles */
.message-in [data-testid="msg-meta"] span,
.message-out [data-testid="msg-meta"] span {
  color: var(--wa-text-time) !important;
}

/* Tick marks */
[data-testid="msg-dblclk-container"] span[data-icon] svg path,
span[data-icon="msg-dblcheck"] path,
span[data-icon="msg-check"] path,
span[data-icon="msg-dblcheck-ack"] path {
  fill: var(--wa-tick) !important;
}

/* Links inside bubbles */
.message-in a,
.message-out a {
  color: var(--wa-text-link) !important;
  text-decoration: underline !important;
  text-underline-offset: 2px !important;
}

/* Forwarded label */
[data-testid="fwd-label"],
.message-in [class*="forward"],
.message-out [class*="forward"] {
  color: var(--wa-text-time) !important;
}

/* Quoted reply inside bubble */
[data-testid="quoted-message"] {
  background-color: #2a0d20 !important;
  border-left: 3px solid var(--wa-accent) !important;
  border-radius: 6px !important;
}

/* ── Compose / input bar ─────────────────────────────────────────────────── */
footer,
[data-testid="conversation-compose-box"] {
  background-color: var(--wa-bg-header) !important;
  border-top: 0.5px solid var(--wa-border) !important;
}

/* The editable message field */
[data-testid="compose-box-input"],
[aria-label="Type a message"],
footer div[contenteditable="true"] {
  background-color: var(--wa-bg-input) !important;
  border: 0.5px solid var(--wa-border-light) !important;
  border-radius: 20px !important;
  color: var(--wa-text-primary) !important;
  caret-color: var(--wa-accent) !important;
}

/* Placeholder */
[data-testid="compose-box-input"]:empty::before,
footer div[contenteditable="true"]:empty::before {
  color: #6a3050 !important;
}

/* Send button */
[data-testid="send"],
[aria-label="Send"],
button[aria-label="Send"] {
  background-color: var(--wa-accent) !important;
  border-radius: 50% !important;
  transition: background 0.15s !important;
}

[data-testid="send"]:hover,
button[aria-label="Send"]:hover {
  background-color: var(--wa-accent-light) !important;
}

[data-testid="send"] svg path,
button[aria-label="Send"] svg path {
  fill: #fff !important;
}

/* Emoji / attach / mic buttons */
footer button svg,
footer [role="button"] svg {
  fill: var(--wa-accent-muted) !important;
}

/* ── Scrollbars ──────────────────────────────────────────────────────────── */
::-webkit-scrollbar {
  width: 4px !important;
  height: 4px !important;
}

::-webkit-scrollbar-track {
  background: transparent !important;
}

::-webkit-scrollbar-thumb {
  background: #4a1530 !important;
  border-radius: 4px !important;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--wa-accent) !important;
}

/* ── Dropdown menus ──────────────────────────────────────────────────────── */
[role="menu"],
[role="listbox"],
div[data-animate-dropdown-item] {
  background-color: #1f0d18 !important;
  border: 0.5px solid var(--wa-border-light) !important;
  border-radius: 10px !important;
  box-shadow: 0 4px 20px rgba(0,0,0,0.6) !important;
}

[role="menu"] [role="menuitem"],
[role="listbox"] [role="option"] {
  color: var(--wa-text-primary) !important;
}

[role="menu"] [role="menuitem"]:hover,
[role="listbox"] [role="option"]:hover {
  background-color: var(--wa-bg-active) !important;
}

/* ── Selection highlight ─────────────────────────────────────────────────── */
::selection {
  background-color: #7a1848 !important;
  color: #f5d0e0 !important;
}
}
